# Apply filters: exists (non-null, non-empty), length < 1000, doesn't begin with merge/update/test (case-insensitive)
import re
def passes(msg):
    if msg is None or msg == '':
        return False
    if len(msg) >= 1000:
        return False
    low = msg.lstrip().lower()
    if low.startswith('merge') or low.startswith('update') or low.startswith('test'):
        return False
    return True

df['ok'] = df['message'].apply(passes)
print(df['ok'].sum())

